ARM = 'left'
TASK_ID = 'bottle_transfer'


class Policy:
    def reset(self, instruction):
        self.task_id = instruction.get("task_id")
        self.robot = instruction.get("robot_profile")
        self.index = 0
        # The plan was built for one specific task/robot; on anything else stay put.
        self.enabled = (self.task_id == TASK_ID and self.robot == 'dual_piper' and
                        ARM in instruction.get("arms", {}))

    def act(self, observation):
        if not self.enabled or self.index >= len(ACTIONS):
            return {"finish": True}
        item = ACTIONS[self.index]
        self.index += 1
        return {
            "arms": {ARM: {"positions": item["positions"],
                            "gripper_width_m": item["gripper_width_m"]}},
            "steps": int(item["steps"]),
        }
